CREATE TABLE notification_account(account_id UUID PRIMARY KEY);
CREATE TABLE notification_preference(account_id UUID NOT NULL REFERENCES notification_account(account_id),channel VARCHAR(8) NOT NULL CHECK(channel IN('IN_APP','EMAIL','SMS','PUSH')),enabled BOOLEAN NOT NULL,version BIGINT NOT NULL DEFAULT 1,PRIMARY KEY(account_id,channel));
CREATE TABLE notification_contact(account_id UUID NOT NULL REFERENCES notification_account(account_id),channel VARCHAR(8) NOT NULL CHECK(channel IN('EMAIL','SMS','PUSH')),ciphertext TEXT NOT NULL,updated_at TIMESTAMPTZ NOT NULL,PRIMARY KEY(account_id,channel));
CREATE TABLE reminder(id UUID PRIMARY KEY,account_id UUID NOT NULL REFERENCES notification_account(account_id),kind VARCHAR(8) NOT NULL CHECK(kind IN('CONTENT','LIVE')),target_id UUID NOT NULL,channel VARCHAR(8) NOT NULL CHECK(channel IN('IN_APP','EMAIL','SMS','PUSH')),due_at TIMESTAMPTZ NOT NULL,expires_at TIMESTAMPTZ NOT NULL,state VARCHAR(12) NOT NULL CHECK(state IN('WAITING','REQUESTED','CANCELLED','EXPIRED')),idempotency_key VARCHAR(128) NOT NULL,fingerprint CHAR(64) NOT NULL,UNIQUE(account_id,idempotency_key));
CREATE UNIQUE INDEX reminder_active_target ON reminder(account_id,kind,target_id,channel) WHERE state IN('WAITING','REQUESTED');
CREATE INDEX reminder_due ON reminder(due_at,id) WHERE state='WAITING';
CREATE TABLE live_notice_state(event_id UUID PRIMARY KEY,version BIGINT NOT NULL,state VARCHAR(16) NOT NULL,fingerprint CHAR(64) NOT NULL,changed_at TIMESTAMPTZ NOT NULL);
CREATE TABLE notification_source(event_id UUID PRIMARY KEY,fingerprint CHAR(64) NOT NULL,received_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE notification_intent(id UUID PRIMARY KEY,account_id UUID NOT NULL REFERENCES notification_account(account_id),template VARCHAR(32) NOT NULL CHECK(template IN('CONTENT_REMINDER','LIVE_STARTED','PAYMENT_FAILED')),cause_id UUID NOT NULL,target_id UUID NOT NULL,channel VARCHAR(8) NOT NULL CHECK(channel IN('IN_APP','EMAIL','SMS','PUSH')),state VARCHAR(16) NOT NULL CHECK(state IN('QUEUED','PENDING','DISPATCHING','DELIVERED','SKIPPED','FAILED','RECONCILE')),expires_at TIMESTAMPTZ NOT NULL,created_at TIMESTAMPTZ NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,next_attempt_at TIMESTAMPTZ NOT NULL,claim_token UUID,claimed_until TIMESTAMPTZ,provider_receipt VARCHAR(255),UNIQUE(account_id,template,cause_id,channel));
CREATE INDEX notification_claimable ON notification_intent(next_attempt_at,id) WHERE state IN('PENDING','DISPATCHING');
CREATE TABLE notification_inbox(intent_id UUID PRIMARY KEY REFERENCES notification_intent(id),account_id UUID NOT NULL REFERENCES notification_account(account_id),template VARCHAR(32) NOT NULL,target_id UUID NOT NULL,created_at TIMESTAMPTZ NOT NULL,read_at TIMESTAMPTZ);
CREATE INDEX notification_inbox_page ON notification_inbox(account_id,created_at DESC,intent_id DESC);
